function model(p) {
  // Illustrative, seeded synthetic data: 20 weeks of active customers (thousands) vs weekly support tickets.
  // A line with two dials (slope, intercept) is trained by full-batch gradient descent on mean squared error.
  // The dials are trained on a standardized customer count z = (x - mean) / sd, so learning rates behave the same
  // whatever the units; slope and intercept are converted back to real units for display.
  let s = 20261003 >>> 0;
  const rnd = () => { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const n = 20, points = [];
  for (let i = 0; i < n; i++) {
    const x = +(2 + 18 * (i + 0.15 + 0.7 * rnd()) / n).toFixed(1);
    const noise = 46 * (rnd() + rnd() + rnd() - 1.5);
    points.push({ x, y: Math.round(60 + 22 * x + noise) });
  }
  const mx = points.reduce((a, q) => a + q.x, 0) / n, my = points.reduce((a, q) => a + q.y, 0) / n;
  const sx = Math.sqrt(points.reduce((a, q) => a + (q.x - mx) ** 2, 0) / n);
  const z = points.map(q => (q.x - mx) / sx);
  const lossAt = (w, b) => points.reduce((a, q, i) => a + (w * z[i] + b - q.y) ** 2, 0) / n;
  const toReal = (w, b) => ({ slope: w / sx, intercept: b - w * mx / sx });
  // Closed-form least squares (normal equations) for comparison
  const lsSlope = points.reduce((a, q) => a + (q.x - mx) * (q.y - my), 0) / points.reduce((a, q) => a + (q.x - mx) ** 2, 0);
  const ls = { slope: lsSlope, intercept: my - lsSlope * mx, loss: lossAt(lsSlope * sx, my) };
  const RATES = [0.001, 0.2, 1.02], RATE_NAMES = ['Too small', 'Just right', 'Too big'];
  const ri = Math.max(0, Math.min(2, Math.round(p.rate))), lr = RATES[ri];
  const steps = Math.max(1, Math.round(p.steps));
  const STARTS = [{ name: 'Flat line', slope: 0, intercept: 120 }, { name: 'Steep line', slope: 48, intercept: -80 }];
  const start = STARTS[Math.max(0, Math.min(1, Math.round(p.start)))];
  let w = start.slope * sx, b = start.intercept + start.slope * mx;
  const history = [];
  for (let k = 0; k <= steps; k++) {
    let gw = 0, gb = 0;
    points.forEach((q, i) => { const r = w * z[i] + b - q.y; gw += 2 * r * z[i] / n; gb += 2 * r / n; });
    const real = toReal(w, b);
    history.push({ step: k, w, b, slope: real.slope, intercept: real.intercept, loss: lossAt(w, b), gw, gb });
    w -= lr * gw; b -= lr * gb;
  }
  const L = history.map(h => h.loss), first = L[0], last = L[steps];
  // "Stops falling": first step after which the loss improves by less than 0.1% per step
  let stallStep = null;
  for (let k = 1; k <= steps; k++) if ((L[k - 1] - L[k]) / L[k - 1] < 0.001 && L[k] <= L[k - 1]) { stallStep = k; break; }
  const grew = last > first;
  const outcome = grew ? 'diverged' : (last - ls.loss) / ls.loss < 0.01 ? 'converged' : 'slow';
  // Playback: hold the start, then step through; early steps get more time (time grows with sqrt of step)
  const duration = +Math.min(14, Math.max(6, 5 + steps * 0.045)).toFixed(2), lead = 0.6, tail = 0.8, span = duration - lead - tail;
  const timeOf = k => +(lead + span * Math.sqrt(k / steps)).toFixed(3);
  const ms = [1, 3, 10, 30, 100].filter(k => k < steps);
  if (stallStep && outcome === 'converged') ms.push(stallStep);
  ms.push(steps);
  const markerSteps = [...new Set(ms)].sort((a, b) => a - b);
  const fin = history[steps], f1 = v => v.toFixed(1), f0 = v => Math.round(v).toLocaleString('en-US');
  const big = v => v >= 1e9 ? +(v / 1e9).toPrecision(3) + ' billion' : v >= 1e6 ? +(v / 1e6).toPrecision(3) + ' million' : v >= 100 ? f0(v) : f1(v);
  const summary = outcome === 'converged'
    ? 'Converged: slope ' + f1(fin.slope) + ', intercept ' + f0(fin.intercept) + ' matches least squares; ' + (stallStep ? 'the error stopped falling around step ' + stallStep + '.' : 'the error is within ' + ((last / ls.loss - 1) * 100).toFixed(1) + '% of the best possible.')
    : outcome === 'slow'
      ? 'Too small: after ' + steps + ' steps the error is ' + (last / ls.loss).toFixed(1) + '× the best possible; the line is only creeping towards the data.'
      : 'Too big: every nudge overshoots, the line flips side to side and the error grows ' + big(last / first) + '×.';
  const yMax = Math.ceil(Math.max(...points.map(q => q.y)) * 1.15 / 100) * 100;
  return {
    points, n, meanX: mx, meanY: my, sdX: sx, ls, lr, rateName: RATE_NAMES[ri], start: start.name, steps, history,
    firstLoss: first, finalLoss: last, growth: last / first, stallStep, outcome, summary,
    xDomain: [0, 22], yDomain: [0, yMax], slopeRange: [-20, 60], interceptRange: [-300, 300],
    timing: { lead, span, tail }, duration, markerSteps, markers: markerSteps.map(timeOf)
  };
}

checkCode:
function check(p) {
  const m = model(p), H = m.history, pts = m.points, n = pts.length;
  // 1. The recorded gradient equals the analytic gradient (central finite differences of the MSE) at every step,
  //    and each step moves the dials by exactly -learning rate x gradient.
  const z = pts.map(q => (q.x - m.meanX) / m.sdX);
  const loss = (w, b) => pts.reduce((a, q, i) => a + (w * z[i] + b - q.y) ** 2, 0) / n;
  let gradErr = 0, stepErr = 0;
  H.forEach((h, k) => {
    const hw = 1e-3 * (1 + Math.abs(h.w)), hb = 1e-3 * (1 + Math.abs(h.b));
    const nw = (loss(h.w + hw, h.b) - loss(h.w - hw, h.b)) / (2 * hw), nb = (loss(h.w, h.b + hb) - loss(h.w, h.b - hb)) / (2 * hb);
    const sc = 1 + Math.abs(nw) + Math.abs(nb);
    gradErr = Math.max(gradErr, Math.abs(h.gw - nw) / sc, Math.abs(h.gb - nb) / sc);
    if (k > 0) { const g = H[k - 1]; stepErr = Math.max(stepErr, Math.abs(h.w - (g.w - m.lr * g.gw)) / (1 + Math.abs(h.w)), Math.abs(h.b - (g.b - m.lr * g.gb)) / (1 + Math.abs(h.b))); }
  });
  const gradOk = gradErr < 1e-6 && stepErr < 1e-9;
  const L = H.map(h => h.loss), last = H[H.length - 1];
  const nonInc = L.every((v, k) => k === 0 || v <= L[k - 1] * (1 + 1e-12));
  // Largest vertical gap between the trained line and the least-squares line over the plotted range
  const gap = Math.max(...m.xDomain.map(x => Math.abs(last.slope * x + last.intercept - (m.ls.slope * x + m.ls.intercept))));
  const gtxt = ' Gradient matches finite differences at all ' + H.length + ' recorded steps (max rel. error ' + gradErr.toExponential(0) + ').';
  if (m.rateName === 'Just right') {
    const ok = gradOk && nonInc && gap < 5;
    return { pass: ok, detail: 'Learning rate ' + m.lr + ': the error falls at every step (' + Math.round(L[0]) + ' to ' + Math.round(last.loss) + ' tickets², least squares ' + Math.round(m.ls.loss) + ') and the final line is within ' + gap.toFixed(2) + ' tickets of the least-squares line.' + gtxt };
  }
  if (m.rateName === 'Too small') {
    const ok = gradOk && nonInc && last.loss > 1.5 * m.ls.loss;
    return { pass: ok, detail: 'Learning rate ' + m.lr + ': the error falls at every step but only from ' + Math.round(L[0]) + ' to ' + Math.round(last.loss) + ' tickets² (least squares ' + Math.round(m.ls.loss) + '), so after ' + m.steps + ' steps the line is still up to ' + Math.round(gap) + ' tickets off.' + gtxt };
  }
  const grows = L.every((v, k) => k === 0 || v > L[k - 1]);
  const flips = H.every((h, k) => k === 0 || Math.sign(h.slope - m.ls.slope) !== Math.sign(H[k - 1].slope - m.ls.slope));
  return { pass: gradOk && grows && flips, detail: 'Learning rate ' + m.lr + ': it oscillates and diverges, the slope jumping to the other side of the best fit at every step while the error grows at every step from ' + Math.round(L[0]).toLocaleString('en-US') + ' to ' + (last.loss >= 1e9 ? +(last.loss / 1e9).toPrecision(3) + ' billion' : last.loss >= 1e6 ? +(last.loss / 1e6).toPrecision(3) + ' million' : Math.round(last.loss).toLocaleString('en-US')) + ' tickets².' + gtxt };
}
